import{_ as e,o,c as r,a7 as s}from"./chunks/framework.C4ZIv4ii.js";const a="/falconcms/screenshots/wholesale-settings.webp",d="/falconcms/screenshots/wholesale-reports.webp",m=JSON.parse('{"title":"Settings & Tools","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/settings.md","filePath":"wholesale/settings.md","lastUpdated":1792170474000}'),n={name:"wholesale/settings.md"};function l(i,t,h,c,p,u){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="settings-tools" tabindex="-1">Settings &amp; Tools <a class="header-anchor" href="#settings-tools" aria-label="Permalink to &quot;Settings &amp; Tools&quot;">​</a></h1><p>Everything in <strong>Wholesale → Settings</strong>, then the reports, emails, text messages and scheduled tasks.</p><p><img src="'+a+'" alt="Wholesale settings"></p><p><em>The top of the settings page: applications, coupons and promotions, never more than retail, who sees prices and the private store.</em></p><hr><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Accept applications</strong></td><td>On</td><td>Shows the application form at <code>/wholesale/apply</code> and in My Account → Wholesale</td></tr><tr><td><strong>Approve applications automatically</strong></td><td>Off</td><td>Otherwise each application waits for you in Wholesale → Customers</td></tr><tr><td><strong>No coupons on wholesale prices</strong></td><td>On</td><td>Wholesale customers cannot apply coupon codes</td></tr><tr><td><strong>No automatic promotions on wholesale prices</strong></td><td>On</td><td>Buy X get Y and other promotions do not apply to wholesale customers</td></tr><tr><td><strong>Never charge more than retail</strong></td><td>On</td><td>When a retail sale is cheaper than the wholesale price, the wholesale customer pays the sale price</td></tr><tr><td><strong>Show the saving</strong></td><td>On</td><td>&quot;You save X%&quot; under the price on product pages</td></tr><tr><td><strong>Who sees prices</strong></td><td>Everyone</td><td>Everyone, signed-in customers only, or wholesale customers only; see <a href="/falconcms/wholesale/pricing.html#who-sees-prices">Prices</a></td></tr><tr><td><strong>Private store</strong></td><td>Off</td><td>Close the storefront to everyone but signed-in or wholesale customers; see below</td></tr><tr><td><strong>Minimum order counts</strong></td><td>Everything in the cart</td><td>Or only items at a wholesale price, for a level&#39;s minimum order</td></tr><tr><td><strong>PO number at checkout</strong></td><td>Optional</td><td>Off, optional or required</td></tr><tr><td><strong>Login page</strong></td><td>Wholesale Login</td><td>The page holding the <code>[falcon_wholesale_login]</code> form; see <a href="/falconcms/wholesale/portal.html">Login &amp; Portal</a></td></tr><tr><td><strong>Price label</strong></td><td>Wholesale price</td><td>The words next to a wholesale price (&quot;Wholesale price · Dealer&quot;)</td></tr><tr><td><strong>Email new applications to</strong></td><td>The shop&#39;s new-order address</td><td>Who hears about a new application</td></tr><tr><td><strong>Terms to accept</strong></td><td>Empty</td><td>When filled, applicants must tick a box with this text</td></tr><tr><td><strong>Quote requests</strong></td><td>Wholesale customers</td><td>Who sees &quot;Request a quote&quot; in the cart: wholesale customers, any signed-in customer, or off</td></tr></tbody></table><h3 id="private-store" tabindex="-1">Private store <a class="header-anchor" href="#private-store" aria-label="Permalink to &quot;Private store&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Off: the shop is open to everyone</strong></td><td>A normal shop</td></tr><tr><td><strong>Signed-in customers only</strong></td><td>Guests are sent to the wholesale login page</td></tr><tr><td><strong>Approved wholesale customers only</strong></td><td>Anyone who is not an approved trade buyer is sent there</td></tr></tbody></table><p>The login, application and My Account pages stay open, and so does the admin.</p><hr><h2 id="credit-accounts-and-invoices" tabindex="-1">Credit accounts and invoices <a class="header-anchor" href="#credit-accounts-and-invoices" aria-label="Permalink to &quot;Credit accounts and invoices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Default days to pay</strong></td><td>30</td><td>For customers buying on account without their own terms</td></tr><tr><td><strong>Overdue accounts</strong></td><td>On</td><td>No new orders on account while anything is overdue</td></tr><tr><td><strong>Remind before due</strong></td><td>3 days</td><td>How many days before a payment is due the customer is reminded. They are reminded again once it is overdue.</td></tr><tr><td><strong>Your BIN / VAT number</strong></td><td>Empty</td><td>Printed on invoices and challans</td></tr><tr><td><strong>Invoice footer</strong></td><td>Empty</td><td>Printed at the bottom: bank details, terms, a thank-you</td></tr></tbody></table><p>See <a href="/falconcms/wholesale/ordering.html#buying-on-account-credit">Buying on account</a> and <a href="/falconcms/wholesale/portal.html#invoices-and-delivery-challans">Invoices</a>.</p><hr><h2 id="text-messages-sms" tabindex="-1">Text messages (SMS) <a class="header-anchor" href="#text-messages-sms" aria-label="Permalink to &quot;Text messages (SMS)&quot;">​</a></h2><p>The plugin texts customers through any SMS provider that has an HTTP API, which covers almost all of them, including the Bangladeshi gateways.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Send SMS</strong></td><td>Off, or <em>Through my SMS provider (HTTP)</em></td></tr><tr><td><strong>Provider URL</strong></td><td>From your provider&#39;s API page. Put <code>{to}</code> where the number goes and <code>{message}</code> where the text goes.</td></tr><tr><td><strong>Method</strong></td><td>GET (everything in the URL) or POST (form fields you list)</td></tr><tr><td><strong>Country code</strong></td><td>Picked from a searchable list of every country. It is added to local numbers that start with 0: with Bangladesh (+880), <code>01711223344</code> becomes <code>+8801711223344</code>. Numbers written with <code>+</code> or <code>00</code> are sent as they are.</td></tr><tr><td><strong>Send when</strong></td><td>Tick the events: account approved, order placed, payment received, payment due or overdue, quote ready</td></tr><tr><td><strong>Messages</strong></td><td>What each text says (below)</td></tr></tbody></table><p><strong>Messages.</strong> Each event has its own text. Start from a ready-made one, in <strong>English or Bangla</strong> (one click puts it in the box), and change it as you like. Placeholders such as <code>{name}</code>, <code>{amount}</code> and <code>{balance}</code> are filled in when it is sent, and a live count shows the characters and SMS parts. An empty box sends the built-in English text. Bangla texts fit 70 characters per SMS instead of 160, so they cost more.</p><p>Save the settings, then use <strong>Send a test SMS</strong> to check them. Staff can also text a customer by hand from the customer&#39;s screen (<strong>Send an SMS</strong>), with ready-made messages to pick from.</p><hr><h2 id="sales-reps" tabindex="-1">Sales reps <a class="header-anchor" href="#sales-reps" aria-label="Permalink to &quot;Sales reps&quot;">​</a></h2><p>Add a rep with a user&#39;s email and a commission percentage; see <a href="/falconcms/wholesale/customers.html#sales-reps">Sales reps</a>.</p><hr><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><ul><li><strong>Create the login page</strong> — makes the Wholesale Login page if it is missing, brings it back from the trash, or publishes it, and sets it as the login page. Its content is never changed.</li><li><strong>Rebuild the price index</strong> — the price filter and sort use what each level pays. The index updates by itself when you save a product, a category or a level, and every night. Rebuild it now if you changed retail prices in bulk (for example by import).</li></ul><hr><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p><strong>Wholesale → Reports</strong> covers a period: the last 30 or 90 days, this month, this year, or dates you choose.</p><p><img src="'+d+'" alt="Wholesale reports"></p><p><em>Revenue, orders, average order, share of all sales, what is owed and overdue, revenue by day, top customers and products, revenue by level, and customers who have gone quiet.</em></p><ul><li><strong>Wholesale revenue, orders, average order</strong> and <strong>share of all sales</strong></li><li><strong>Owed on account</strong> and <strong>overdue</strong></li><li><strong>Revenue by day</strong> and <strong>by level</strong></li><li><strong>Top customers</strong> (company members counted with their company), with a CSV download</li><li><strong>Top products</strong></li><li><strong>Gone quiet</strong> — customers with no order in 30, 60, 90 or 180 days</li><li><strong>Sales reps</strong> — orders, revenue and commission per rep</li></ul><p>Cancelled, failed and refunded orders are left out.</p><hr><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><p>The plugin emails customers and staff when:</p><table tabindex="0"><thead><tr><th>Email</th><th>To</th></tr></thead><tbody><tr><td>Application received</td><td>You (the address in Settings)</td></tr><tr><td>Application approved or rejected (with your reason)</td><td>The applicant</td></tr><tr><td>Team invitation</td><td>The person invited to a company</td></tr><tr><td>Order needs approval / approved / declined</td><td>Owners and managers / the buyer</td></tr><tr><td>Quote ready</td><td>The customer</td></tr><tr><td>Payment due soon / overdue</td><td>Credit customers</td></tr><tr><td>Reorder reminder</td><td>Whoever set a reminder on a saved list</td></tr><tr><td>New order of a customer</td><td>Their sales rep</td></tr></tbody></table><p>Every wholesale email uses one responsive layout with your shop email header image (or your logo, or your shop name), your theme&#39;s primary colour and the shop email footer text. A theme can override any of them under <code>falcon-wholesale::emails.*</code>.</p><hr><h2 id="scheduled-tasks" tabindex="-1">Scheduled tasks <a class="header-anchor" href="#scheduled-tasks" aria-label="Permalink to &quot;Scheduled tasks&quot;">​</a></h2><p>These run through the Laravel scheduler, so the site&#39;s cron must call <code>php artisan schedule:run</code> every minute (see <a href="/falconcms/guide/upgrade.html#scheduled-tasks">Scheduled Tasks</a>).</p><table tabindex="0"><thead><tr><th>Command</th><th>When</th><th>What it does</th></tr></thead><tbody><tr><td><code>falcon:wholesale-reindex</code></td><td>Daily, 03:30</td><td>Rebuilds the price index</td></tr><tr><td><code>falcon:wholesale-credit-reminders</code></td><td>Daily, 09:00</td><td>Emails (and texts) payments due soon and overdue</td></tr><tr><td><code>falcon:wholesale-list-reminders</code></td><td>Daily, 09:15</td><td>Sends saved-list reorder reminders that are due</td></tr></tbody></table><hr><h2 id="shortcodes" tabindex="-1">Shortcodes <a class="header-anchor" href="#shortcodes" aria-label="Permalink to &quot;Shortcodes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcode</th><th>What it shows</th></tr></thead><tbody><tr><td><code>[falcon_wholesale_login]</code></td><td>The wholesale login form; options <code>title</code>, <code>redirect</code>, <code>apply=&quot;no&quot;</code></td></tr><tr><td><code>[falcon_wholesale_apply]</code></td><td>A link to the application form</td></tr><tr><td><code>[falcon_wholesale_only]…[/falcon_wholesale_only]</code></td><td>Content for wholesale customers only; options <code>message</code>, <code>login=&quot;yes&quot;</code></td></tr><tr><td><code>[falcon_retail_only]…[/falcon_retail_only]</code></td><td>Content hidden from wholesale customers</td></tr></tbody></table>',45)])])}const y=e(n,[["render",l]]);export{m as __pageData,y as default};
